    var config = normalizeWorkHoursConfig(rule.workHoursConfig);
    if (config.mode === 'capped') {
      return base + '（每日最多 ' + config.maxHoursPerDay + ' 小时）';
    }
    return base + (rule.clockin === 'noclock' ? '（按照实际录入工时）' : '（按照实际打卡工时）');
