            employees.push({employeeId:e.f.employeeId,name:e.f.name,role:e.f.role,receiverIndex:index,employeeWeight:e.employeeWeight,attendanceStatus:e.present?'clock':'absent',hours:e.h,hoursSource:e.edit.hours!==undefined?'manual':'attendance',percentage:ratios[i]/100,amount:amounts[i]/100,orderCount:(e.f.orders||[]).length});
