  doc.write('<table><thead><tr>' + ['Employee','Role','Punch Hours','Allocation Hours','Original Tips','Deducted','Received','Net Adjustment','Final Amount','Issue Reasons'].map(function(label) { return '<th>' + label + '</th>'; }).join('') + '</tr></thead><tbody>');
  rows.forEach(function(row) { doc.write('<tr>' + row.map(function(cell) { return '<td>' + escH(cell) + '</td>'; }).join('') + '</tr>'); });
