    function restoreSummaryUiState(deferRender) {
      var saved = TipOutSummaryUi.readSummaryHistoryState(history.state);
      var signature = saved ? JSON.stringify(saved) : '__no_summary_state__';
      if (signature === restoredSummaryStateSignature) return false;
      restoredSummaryStateSignature = signature;
      if (!saved) return false;

      var queryView = new URLSearchParams(window.location.search).get('view');
      activeSummaryView = TipOutSummaryUi.resolveSummaryView(history.state, queryView);
      if (TipOutSummaryDateSort.isValidDateRange(saved.dateStart, saved.dateEnd)) {
        document.getElementById('dateStart').value = saved.dateStart;
        document.getElementById('dateEnd').value = saved.dateEnd;
      } else {
        applyDefaultSummaryDateRange();
      }
      document.getElementById('storeSelect').value = saved.store || '';
      if(isStoreSummaryRoute())initializeDashboardPage();
      dateSummaryFilters = {
        allocationStatus: saved.dateAllocationStatus || '',
        businessStatus: saved.dateBusinessStatus === 'open' || saved.dateBusinessStatus === 'closed' ? saved.dateBusinessStatus : '',
        payoutStatus: ['pending-payout', 'paid', 'not-required'].indexOf(saved.datePayoutStatus) >= 0 ? saved.datePayoutStatus : ''
      };
      employeeSummaryFilters = {
        role: saved.employeeSummaryRole || '',
        employeeScope: saved.employeeSummaryScope || { mode: 'all', ids: [] },
        statuses: []
      };
      employeeSummarySort = {
        key: ['employee', 'hours', 'finalAmount'].indexOf(saved.employeeSortKey) >= 0 ? saved.employeeSortKey : 'finalAmount',
        direction: saved.employeeSortDirection === 'asc' ? 'asc' : 'desc'
      };
      var employeeRole = document.getElementById('employeeSummaryRoleFilter');
      var employeeStatus = document.getElementById('employeeSummaryStatusFilter');
      var dateAllocationStatus = document.getElementById('dateAllocationStatusFilter');
      var dateBusinessStatus = document.getElementById('dateBusinessStatusFilter');
      var datePayoutStatus = document.getElementById('datePayoutStatusFilter');
      if (employeeRole) employeeRole.value = employeeSummaryFilters.role || '';
      if (employeeStatus) employeeStatus.value = employeeSummaryFilters.statuses[0] || '';
      if (dateAllocationStatus) dateAllocationStatus.value = dateSummaryFilters.allocationStatus;
      if (dateBusinessStatus) dateBusinessStatus.value = dateSummaryFilters.businessStatus;
      if (datePayoutStatus) datePayoutStatus.value = dateSummaryFilters.payoutStatus;
      invalidateDayPipelineCache();
      syncSummaryViewUi();
      if (!deferRender) renderDailySummaryList();

      requestAnimationFrame(function() {
        window.scrollTo(0, Number(saved.scrollY) || 0);
        var row = null;
        if (saved.returnDate) row = document.querySelector('[data-date="' + saved.returnDate + '"]');
        if (!row && saved.returnEmployeeId) {
          var employeeRows = document.querySelectorAll('[data-employee-id]');
          for (var i = 0; i < employeeRows.length; i++) {
            if (employeeRows[i].dataset.employeeId === saved.returnEmployeeId) {
              row = employeeRows[i];
              break;
            }
          }
        }
        if (row) row.focus({ preventScroll: true });
      });
      return true;
    }

    function openDailyDetail(dateKey) {
      if (!validateSummaryDateRange(true)) return;
      var snapshotRow = buildDailyDataset(getFilteredEmployees()).filter(function(row) { return row.dateKey === dateKey; })[0];
      if (snapshotRow && snapshotRow.businessStatusResult.status === 'closed') {
        showNotification('当天未营业，无法查看分配明细', 'warning');
        return;
      }
      if (!snapshotRow || !snapshotRow.allocated) {
        confirmAction('该日期尚未分配小费，请先完成分配后查看明细', null, {
          title: '暂无法查看分配明细', okText: '知道了', hideCancel: true
        });
        return;
      }
      captureSummaryUiState(dateKey, '');
      var store = (document.getElementById('storeSelect') || {}).value || '';
      if (snapshotRow) {
        try {
          sessionStorage.setItem('tipout-date-pool-summary-v1', JSON.stringify({ dateKey: dateKey, store: store, poolSummary: snapshotRow.poolSummary }));
        } catch (error) { /* detail page can rebuild a fallback projection */ }
      }
      window.location.href = TipOutSummaryUi.buildDetailUrl({
        date: dateKey,
        store: store,
        fromSummary: true
      });
    }

