      ['allocationStore','allocationDateStart','allocationDateEnd'].forEach(function(id) { document.getElementById(id).disabled = false; });
      document.getElementById('confirmAllocateBtn').style.display = '';
      document.getElementById('confirmTipOverwriteBtn').style.display = 'none';
      document.getElementById('tipAllocationModalTitle').textContent = '分配小费';
      document.getElementById('tipAllocationModalDescription').style.display = '';
      document.querySelectorAll('#tipAllocationModal .form-group').forEach(function(group) { group.style.display = ''; });
