    function loadTipsConditionsObject(value) {
      var container = document.getElementById('tipsConditionsContainer');
      if (!container) return;
      container.innerHTML = '';
      existingTipsConditions = {};
      var cond = JSON.parse(JSON.stringify(value || {}));
      tipsDrawerSavedTipTypes = [];
      tipsDrawerRetainedConditions = {};
      if (editingDeductTipsCardId) {
        tipsDrawerSavedTipTypes = Array.isArray(cond.tipTypes) ? cond.tipTypes.slice() : [];
        if (tipsDrawerSavedTipTypes.length) cond.tipType = tipsDrawerSavedTipTypes.length === 1 ? tipsDrawerSavedTipTypes[0] : '__saved_tip_types__';
        delete cond.tipTypes;
        Object.keys(cond).forEach(function(key) {
          if (['role','employee','employeeRoles','area','orderType','hours','tipType','containsProduct','shift','weekdays'].indexOf(key) < 0) {
            tipsDrawerRetainedConditions[key] = cond[key]; delete cond[key];
          }
        });
      }
      if (cond && typeof cond === 'object') {
        normalizeConditionsRoleEmployeeExclusive(cond);
        sortPoolConditionLoadKeys(Object.keys(cond)).forEach(function(type) {
          if (type === 'containsAlcohol') return;
          if (type === 'weekdays') {
            addTipsCondition('weekday', true);
            setTipsConditionValue('weekday', cond.weekdays);
            return;
          }
          addTipsCondition(type, true);
          if (type === 'role') setTipsConditionValue(type, { role: cond.role || [] });
          else if (type === 'employee') setTipsConditionValue(type, { employeeRoles: cond.employeeRoles, employees: cond.employee });
          else {
            if (type === 'tipType') {
              var select = document.querySelector('#tips-cond-tipType select');
              if (select && cond.tipType && !Array.from(select.options).some(function(option) { return option.value === cond.tipType; })) {
                var option = document.createElement('option'); option.value = cond.tipType;
                option.textContent = cond.tipType === '__saved_tip_types__' ? tipsDrawerSavedTipTypes.join('、') : cond.tipType;
                select.appendChild(option);
              }
            }
            setTipsConditionValue(type, cond[type]);
          }
        });
      }
      var previousNote = document.getElementById('tipsRetainedConditions'); if (previousNote) previousNote.remove();
      if (Object.keys(tipsDrawerRetainedConditions).length) {
        var note = document.createElement('p'); note.id = 'tipsRetainedConditions'; note.className = 'tipout-condition-retained';
        note.textContent = '其他已保存条件：' + formatSalesCondForDisplay(tipsDrawerRetainedConditions, true) + '。提交将保留这些条件。';
        container.appendChild(note);
      }
      updateTipsConditionMenu();
      syncContributorScopeHint('tipsDrawer', !!editingDeductTipsCardId);
    }
