    function setManualConditionValue(type, value) {
      var card = document.getElementById('manual-cond-' + type);
      if (!card) return;
      if (type === 'role' && value) {
        var roleMs = card.querySelector('.role-role-select');
        var roleArr = Array.isArray(value) ? value : (value.role || []);
        if (roleMs) {
          roleMs.querySelectorAll('input[type="checkbox"]').forEach(function(cb) {
            cb.checked = roleArr.indexOf(cb.value) >= 0;
          });
          if (roleMs.id) refreshMultiTags(roleMs.id);
        }
      } else if (type === 'employee') {
        applyStandaloneEmployeeConditionToCard(card, value);
      } else if (type === 'hours' && value && (value.start || value.end)) {
        var inputs = card.querySelectorAll('input[type="time"]');
        if (inputs[0] && value.start) inputs[0].value = value.start;
        if (inputs[1] && value.end) inputs[1].value = value.end;
      } else if (type === 'shift') {
        var arr = Array.isArray(value) ? value : (value != null && value !== '' ? [String(value)] : []);
        mergeShiftsFromSaved(arr);
        var shiftMs = card.querySelector('.shift-condition-select');
        if (shiftMs) {
          var dropdown = shiftMs.querySelector('.multi-select-dropdown');
          if (dropdown) dropdown.innerHTML = getShiftMultiSelectOptionsHtml();
          shiftMs.querySelectorAll('input[type="checkbox"]').forEach(function(cb) {
            cb.checked = arr.indexOf(cb.value) >= 0;
          });
          if (shiftMs.id) refreshMultiTags(shiftMs.id);
        }
      } else if (type === 'weekday') {
        applyWeekdayConditionValue(card, value);
      }
    }

